#!/usr/bin/env python3
"""Describe only executed external programs; never infer a compatibility rate."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
roms=json.loads((ROOT/'testdata/m8-roms/manifest.json').read_text())
game=json.loads((ROOT/'testdata/m8-game/manifest.json').read_text())
matrix=[]
for e in roms['titles']:
 title=e['id'];pal=title in ['hdma-repeat-entry','hdma-to-cgram','window-mask-logic','vmain-mode7-image-with-8bit-remapping','inidisp_enable_display_mid_frame','inidisp_brightness_delay']
 matrix.append({**e,'source':roms['source'],'sourceCommit':roms['commit'],'testedRegion':'NTSC plus PAL' if pal else 'NTSC; PAL untested','hardwareFamily':'analytical separate-chip2/1/3, no board certification','boot':'exact native software comparisons at fields24/25','menu':'window-control text/states' if title=='window-mask-logic' else 'not a game menu','scene':'diagnostic output, not a commercial game scene','audio':'not assessed as sounding evidence','inputs':'five distinct actual states via Right/Left/L/R/Select replay' if title=='window-mask-logic' else 'application consumption not asserted','sram':'not applicable; no cartridge RAM','state':'complete snapshot3 -> 6 against unloaded uninterrupted execution','longSegment':'40 fields with input' if title=='window-mask-logic' else '24/25 fields; no long-session claim','chipsTested':[]})
matrix.append({'id':'unnamed-snes-game','path':'testdata/m8-game/unnamed-snes-game.sfc','sha256':game['sha256'],'source':game['source'],'sourceCommit':game['commit'],'license':game['license'],'region':'NTSC','testedRegion':'NTSC; PAL untested','mapper':'HiROM','chipsTested':[],'hardwareFamily':'analytical separate-chip2/1/3; no board certification','boot':'title checkpoint120, native images match both references','menu':'file-select checkpoint175, native images match both references','scene':'playground/00-01-test checkpoint300 matches both references; numbered floor is source second-layers/sl_floor.png','audio':'nonzero title audio and exact own snapshot130 -> 135; initial32768-pair reference checkpoint passes; full sequence has explicitly red differences, see accuracy reports and audio repro','inputs':'Start150â€“151, B210â€“211 creates file/room; Right270â€“289; B310â€“311 and Down340â€“359 in long replay','sram':'4096 bytes CPU-created, raw battery roundtrip and both reference comparisons pass with common zero battery input','state':'snapshot300 -> 305 complete state and stereo tail; room source selects song blank, so this tail is intentionally silent','longSegment':'600 raw fields (~10 nominal seconds); exact native image/SRAM comparison, not hours-long validation','replays':'testdata/m8-console/manifest.json and m8-console-own-ipl/manifest.json'})
output={'schema':'m8-executed-title-matrix-v1','accuracyReport':'separate red software accuracy inventories; no compatibility percentage','untested':['commercial titles (none present locally)','ExLoROM/ExHiROM external titles','enhancement chips DSP1/2/3/4, SuperFX, SA1, CX4, SDD1, SPC7110, RTC, OBC1, ST01x','mouse, multitap, SuperScope and expansion systems','physical board/reset/electrical certification'],'titles':matrix}
(ROOT/'testdata/m8-title-matrix.json').write_text(json.dumps(output,indent=2)+'\n',newline='\n',encoding='utf-8')
lines=['# M8 executed title matrix','','Full hashes, sources, licenses, region/mapper/chips and separate functional statuses are in [the machine-readable matrix](../testdata/m8-title-matrix.json). Exact input plans and checkpoints are pinned in both console manifests. All images below are actual native software comparisons; none is a hardware certificate.','','| External program | ROM SHA256 prefix | Region tested | Boot/diagnostic | Inputs | State | Audio / SRAM |','|---|---|---|---|---|---|---|']
for e in matrix[:-1]:lines.append(f"| {e['id']} | {e['sha256'][:12]} | {'NTSC/PAL' if 'plus PAL' in e['testedRegion'] else 'NTSC'} | exact24/25 | {'5 changed states' if e['id']=='window-mask-logic' else 'not asserted'} | 3 -> 6 pass | sound untested / no SRAM |")
lines+=['','All20 programs are unchanged Zlib LoROM inputs with no enhancement chip. Their output is a diagnostic scene; boot success does not assert game compatibility. Window controls run40 fields; other checkpoints run24/25.','','The unchanged MIT/CC-licensed HiROM **unnamed-snes-game** tech demo (`'+game['sha256']+'`) executes title120, file menu175, active room300 and segment600. Both references agree with native images and4096-byte SRAM. The numbered1/2 floor matches current source `sl_floor.png`; the older README screenshot is not an oracle. Title music is nonzero and snapshot130 -> 135 resumes exactly. Snapshot300 -> 305 covers input-created room/SRAM and its intentionally silent `blank` song. Raw battery persistence roundtrips; fault-injection/atomic frontend persistence remains M9.','','Initial32768 native stereo pairs match both references. Full sequences retain red nominal-frequency and unresolved same-frequency differences. Those rows are never labeled passed audio compatibility. See [M8 contract](m8-compatibility-contract.md) and [audio repro](../testdata/m8-audio-repros.json). This is roughly10 seconds of game flow, not a long-session or realtime claim.','','Commercial games, other external mapper families, chips and peripherals are explicitly untested. Internal audio and SETINI diagnostics appear separately in the console reports and are excluded from this external-title table.']
(ROOT/'docs/m8-title-matrix.md').write_text('\n'.join(lines)+'\n',newline='\n',encoding='utf-8')
